		$('.popup .btn_x').click(function(){
			$('body').css({"overflow": ""});
			$('.popup').addClass('hide');
		});
		$('.popup .jq_x').click(function(){
			$('body').css({"overflow": ""});
			$('.popup').addClass('hide');
		});
		/* LAYER */
		$('.jq_layer').click(function(){
			$('.layer').hide();
